"""PWA manifest and installable asset helpers.

Keep web-app metadata and branded assets outside the production implementation
module so the legacy production routes can bind to stable, tested values.
"""

from __future__ import annotations

import base64
import json

from fastapi import FastAPI
from fastapi.responses import Response


ICON_SVG = """<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 512 512">
<rect width="512" height="512" rx="112" fill="#5362e8"/>
<path fill="#fff" d="M100 126c66-20 116-6 156 29v252c-41-30-92-40-156-21V126zm312 0c-66-20-116-6-156 29v252c41-30 92-40 156-21V126z"/>
</svg>"""

ICON_180_PNG = base64.b64decode("")
ICON_192_PNG = base64.b64decode("")
ICON_512_PNG = base64.b64decode("")


def build_manifest(asset_version: str = "924") -> str:
    payload = {
        "name": "长缨辅学",
        "short_name": "长缨辅学",
        "id": "/",
        "start_url": "/?source=pwa",
        "scope": "/",
        "display": "standalone",
        "background_color": "#f6f7fb",
        "theme_color": "#5362e8",
        "icons": [
            {
                "src": f"/icon-192.png?v={asset_version}",
                "sizes": "192x192",
                "type": "image/png",
                "purpose": "any maskable",
            },
            {
                "src": f"/icon-512.png?v={asset_version}",
                "sizes": "512x512",
                "type": "image/png",
                "purpose": "any maskable",
            },
        ],
    }
    return json.dumps(payload, ensure_ascii=False, separators=(",", ":"))


def install_favicon_route(app: FastAPI) -> None:
    """Serve a same-origin favicon without adding another asset dependency."""

    if any(getattr(route, "path", None) == "/favicon.ico" for route in app.routes):
        return

    @app.get("/favicon.ico", include_in_schema=False)
    def favicon() -> Response:
        return Response(
            ICON_180_PNG,
            media_type="image/png",
            headers={"Cache-Control": "public, max-age=86400"},
        )


__all__ = [
    "ICON_180_PNG",
    "ICON_192_PNG",
    "ICON_512_PNG",
    "ICON_SVG",
    "build_manifest",
    "install_favicon_route",
]
